import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:intl/intl.dart' hide TextDirection;
import 'package:solar_icons/solar_icons.dart';

void main() => runApp(const ProviderScope(child: MyFinanceApp()));

final transactionsProvider = StateNotifierProvider<TransactionController,
    List<FinanceTransaction>>((ref) => TransactionController());

final selectedTabProvider = StateProvider<int>((ref) => 0);
final themeModeProvider = StateProvider<ThemeMode>((ref) => ThemeMode.dark);
final accentColorProvider = StateProvider<Color>((ref) => accentPresets.first);

const accentPresets = <Color>[
  Color(0xFFFF9F43),
  Color(0xFF5B8DEF),
  Color(0xFF9B8AFB),
  Color(0xFF65D7A9),
  Color(0xFFFF6B81),
  Color(0xFFFFC24B),
  Color(0xFF4FD1E8),
];

class FinanceTransaction {
  final String title;
  final String category;
  final double amount;
  final bool income;
  final DateTime date;
  const FinanceTransaction({
    required this.title,
    required this.category,
    required this.amount,
    required this.income,
    required this.date,
  });
}

class TransactionController extends StateNotifier<List<FinanceTransaction>> {
  TransactionController()
      : super([
          FinanceTransaction(
            title: 'Gaji Bulanan',
            category: 'Gaji',
            amount: 8500000,
            income: true,
            date: DateTime(2026, 8, 23),
          ),
          FinanceTransaction(
            title: 'Makan siang',
            category: 'Makanan',
            amount: 45000,
            income: false,
            date: DateTime(2026, 8, 23),
          ),
          FinanceTransaction(
            title: 'Transportasi',
            category: 'Transportasi',
            amount: 120000,
            income: false,
            date: DateTime(2026, 8, 22),
          ),
          FinanceTransaction(
            title: 'Belanja bulanan',
            category: 'Belanja',
            amount: 680000,
            income: false,
            date: DateTime(2026, 8, 20),
          ),
        ]);

  void add(String title, double amount, bool income) {
    state = [
      FinanceTransaction(
        title: title,
        category: 'Lainnya',
        amount: amount,
        income: income,
        date: DateTime.now(),
      ),
      ...state,
    ];
  }
}

class AppColors extends ThemeExtension<AppColors> {
  final Color accent;
  final Color onAccent;
  final Color background;
  final Color surface;
  final Color surfaceAlt;
  final Color border;
  final Color textPrimary;
  final Color textMuted;
  final Color positive;

  const AppColors({
    required this.accent,
    required this.onAccent,
    required this.background,
    required this.surface,
    required this.surfaceAlt,
    required this.border,
    required this.textPrimary,
    required this.textMuted,
    required this.positive,
  });

  @override
  AppColors copyWith({
    Color? accent,
    Color? onAccent,
    Color? background,
    Color? surface,
    Color? surfaceAlt,
    Color? border,
    Color? textPrimary,
    Color? textMuted,
    Color? positive,
  }) {
    return AppColors(
      accent: accent ?? this.accent,
      onAccent: onAccent ?? this.onAccent,
      background: background ?? this.background,
      surface: surface ?? this.surface,
      surfaceAlt: surfaceAlt ?? this.surfaceAlt,
      border: border ?? this.border,
      textPrimary: textPrimary ?? this.textPrimary,
      textMuted: textMuted ?? this.textMuted,
      positive: positive ?? this.positive,
    );
  }

  @override
  AppColors lerp(ThemeExtension<AppColors>? other, double t) {
    if (other is! AppColors) return this;
    return AppColors(
      accent: Color.lerp(accent, other.accent, t)!,
      onAccent: Color.lerp(onAccent, other.onAccent, t)!,
      background: Color.lerp(background, other.background, t)!,
      surface: Color.lerp(surface, other.surface, t)!,
      surfaceAlt: Color.lerp(surfaceAlt, other.surfaceAlt, t)!,
      border: Color.lerp(border, other.border, t)!,
      textPrimary: Color.lerp(textPrimary, other.textPrimary, t)!,
      textMuted: Color.lerp(textMuted, other.textMuted, t)!,
      positive: Color.lerp(positive, other.positive, t)!,
    );
  }
}

extension AppColorsX on BuildContext {
  AppColors get colors => Theme.of(this).extension<AppColors>()!;
}

AppColors _palette(Brightness brightness, Color accent) {
  final onAccent = ThemeData.estimateBrightnessForColor(accent) == Brightness.dark
      ? Colors.white
      : const Color(0xFF241708);
  if (brightness == Brightness.dark) {
    return AppColors(
      accent: accent,
      onAccent: onAccent,
      background: const Color(0xFF0F1115),
      surface: const Color(0xFF181B21),
      surfaceAlt: const Color(0xFF22262E),
      border: Colors.transparent,
      textPrimary: const Color(0xFFF1F3F5),
      textMuted: const Color(0xFF8B929D),
      positive: const Color(0xFF4ADE80),
    );
  }
  return AppColors(
    accent: accent,
    onAccent: onAccent,
    background: const Color(0xFFF4F6F8),
    surface: Colors.white,
    surfaceAlt: const Color(0xFFEEF0F4),
    border: Colors.transparent,
    textPrimary: const Color(0xFF1A1D21),
    textMuted: const Color(0xFF6B7280),
    positive: const Color(0xFF10B981),
  );
}

ThemeData _buildTheme(Brightness brightness, Color accent) {
  final palette = _palette(brightness, accent);
  final base = brightness == Brightness.dark ? ThemeData.dark() : ThemeData.light();
  return base.copyWith(
    brightness: brightness,
    useMaterial3: true,
    scaffoldBackgroundColor: palette.background,
    colorScheme: ColorScheme.fromSeed(seedColor: accent, brightness: brightness),
    extensions: [palette],
    textTheme: base.textTheme.apply(fontFamily: 'Satoshi'),
    primaryTextTheme: base.primaryTextTheme.apply(fontFamily: 'Satoshi'),
  );
}

class MyFinanceApp extends ConsumerWidget {
  const MyFinanceApp({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final themeMode = ref.watch(themeModeProvider);
    final accent = ref.watch(accentColorProvider);
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'My Finance',
      themeMode: themeMode,
      theme: _buildTheme(Brightness.light, accent),
      darkTheme: _buildTheme(Brightness.dark, accent),
      home: const HomeShell(),
    );
  }
}

